// Sample / JSON-payload mode. index.html posts a form field "payload"
// containing canonical {invoice, pos, opts}.
const body = ($input.first().json.body) || {};
let payload = body.payload;
if (!payload) { throw new Error('No JSON payload. Send {payload:{...}} (sample), or upload PDFs.'); }
if (typeof payload === 'string') payload = JSON.parse(payload);
return [{ json: payload }];

// The webhook stores uploaded files under binary keys that vary by n8n version
// (invoice/po, or file0/file1, or data/data1...). Normalise them to 'invoice' and
// 'po' so the two Extract-from-File nodes have a stable field to read.
// Strategy: filename hint first (…invoice…, …po/purchase/order…), else upload order
// (the front-end always sends the invoice first, the PO second).
const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin);
if (keys.length < 2) {
  throw new Error('Expected 2 uploaded files (invoice + PO). Binary keys present: [' + keys.join(', ') + ']');
}
let invKey, poKey;
for (const k of keys) {
  const n = String(bin[k].fileName || '').toLowerCase();
  if (!invKey && /inv/.test(n)) invKey = k;
  else if (!poKey && /(purchase|order|\bpo\b|_po|po[-_ ])/.test(n)) poKey = k;
}
invKey = invKey || keys[0];
poKey = poKey || keys.find((k) => k !== invKey) || keys[1];
return [{ json: item.json, binary: { invoice: bin[invKey], po: bin[poKey] } }];

'use strict';
/*
 * parse_text.js — FREE, key-less parser. Turns the plain text of an invoice / PO
 * (from pypdf locally, or n8n's built-in "Extract from File" node) into the
 * canonical schema, using label regexes for the header fields and a header-driven
 * column mapper for line items. No OCR service, no API key, no cost.
 *
 * Works on born-digital (text-layer) PDFs. Scanned images have no text layer — for
 * those you'd add real OCR later (the Nanonets branch is still in the workflow).
 *
 * Portable: runs in Node (require) and in an n8n Code node.
 */

const GSTIN_RE = /\b\d{2}[A-Z]{5}\d{4}[A-Z][0-9A-Z]Z[0-9A-Z]\b/;

const toNum = (s) => {
  if (s == null || s === '') return null;
  // extract the FIRST number token, so trailing text ("11,800.00 (incl. GST)") is ignored
  const m = String(s).match(/-?\d[\d,]*\.?\d*/);
  if (!m) return null;
  const n = Number(m[0].replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
};

// grab a specific tax amount (CGST/SGST/IGST), even when several share one line
// ("CGST 9%: 900.00    SGST 9%: 900.00") — take the last decimal number in this
// label's own segment, after dropping the rate% and any following tax label.
function grabTax(text, label) {
  const m = text.match(new RegExp(label + '[^\\n]*', 'i'));
  if (!m) return null;
  let seg = m[0].replace(new RegExp('^' + label, 'i'), '')
    .replace(/\b(cgst|sgst|igst)\b.*/i, '');
  const nums = seg.match(/\d[\d,]*\.\d{2}/g) || seg.match(/\d[\d,]*/g) || [];
  return nums.length ? toNum(nums[nums.length - 1]) : null;
}

// dates: DD-MM-YYYY, DD/MM/YYYY, YYYY-MM-DD, "10 Jun 2025" → ISO
function toIso(s) {
  if (!s) return '';
  s = s.trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  const MON = { jan: '01', feb: '02', mar: '03', apr: '04', may: '05', jun: '06',
    jul: '07', aug: '08', sep: '09', oct: '10', nov: '11', dec: '12' };
  m = s.match(/^(\d{1,2})\s+([A-Za-z]{3,})\s+(\d{4})$/);
  if (m && MON[m[2].slice(0, 3).toLowerCase()]) {
    return `${m[3]}-${MON[m[2].slice(0, 3).toLowerCase()]}-${m[1].padStart(2, '0')}`;
  }
  return s;
}

const lines = (t) => String(t || '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean);

// Capture a field value after its label, stopping at the NEXT label (a "Word:"
// pattern) or a 2+ space gap or end of line. Works whether the PDF extractor keeps
// wide gaps (pypdf) or collapses them to single spaces (n8n's Extract from File):
//   "Invoice No: INV-1001 Invoice Date: 10-06-2025" → invoice no = "INV-1001".
const STOP = '(?=\\s{2,}|\\s[A-Za-z][A-Za-z ./]{1,22}:|$)';
function fieldValue(text, labels) {
  for (const lab of labels) {
    const re = new RegExp(lab + '\\s*[:#]?\\s*([^\\n]*?)' + STOP, 'im');
    const m = text.match(re);
    if (m && m[1].trim()) return m[1].trim();
  }
  return '';
}
// For ids (invoice/PO/PR numbers): the value is a single token containing a digit.
function idValue(text, labels) {
  for (const lab of labels) {
    const re = new RegExp(lab + '\\s*[:#]?\\s*([A-Za-z0-9][A-Za-z0-9/_-]*)', 'im');
    const m = text.match(re);
    if (m && m[1] && /\d/.test(m[1])) return m[1].trim();
  }
  return '';
}

// Detect the table columns from the header by KEYWORD POSITION (handles multi-word
// headers like "Unit Price" and single-spaced text), returning them left-to-right.
const COL_SCAN = [
  [/\bsl\b|s\.?\s*no\b|^#/i, 'sl'],
  [/description|item|particular/i, 'description'],
  [/hsn|sac/i, 'hsn_sac'],
  [/qty|quantity/i, 'quantity'],
  [/unit\s*price|\brate\b|\bprice\b/i, 'unit_price'],
  [/gst|tax/i, 'gst_rate'],
  [/amount|value/i, 'amount'],
];
function headerColumns(headerLine) {
  const found = [];
  for (const [re, key] of COL_SCAN) {
    const m = headerLine.match(re);
    if (m && m.index != null) found.push({ key, idx: m.index });
  }
  const seen = new Set();
  return found.sort((a, b) => a.idx - b.idx)
    .filter((f) => !seen.has(f.key) && seen.add(f.key)).map((f) => f.key);
}
function assignCol(rec, key, val) {
  if (!key || key === 'sl' || val == null) return;
  if (key === 'description') rec.description = (rec.description ? rec.description + ' ' : '') + val;
  else if (key === 'hsn_sac') rec.hsn_sac = String(val).replace(/\s/g, '');
  else if (key === 'quantity') rec.quantity = toNum(val);
  else if (key === 'unit_price') { rec.unit_price = toNum(val); rec.rate = toNum(val); }
  else if (key === 'gst_rate') { const n = toNum(val); rec.gst_rate = n == null ? null : (n > 1 ? n / 100 : n); }
  else if (key === 'amount') rec.amount = toNum(val);
}

function parseLineItems(ls) {
  const hIdx = ls.findIndex((l) => /description|item|particular/i.test(l)
    && /(amount|qty|quantity|rate|value)/i.test(l));
  if (hIdx < 0) return [];
  const cols = headerColumns(ls[hIdx]);
  const descIdx = cols.indexOf('description');
  if (descIdx < 0) return [];
  const pre = cols.slice(0, descIdx);        // columns before description (e.g. Sl)
  const post = cols.slice(descIdx + 1);      // columns after description (numbers)
  const items = [];
  let lineNo = 1;
  for (let i = hIdx + 1; i < ls.length; i++) {
    const l = ls[i];
    if (/taxable|grand\s*total|po\s*total|sub\s*total|^total\b|cgst|sgst|igst|amount\s*in\s*words|payment|terms|remit/i.test(l)) break;
    const toks = l.split(/\s+/).filter(Boolean);
    if (toks.length < pre.length + post.length + 1) continue;   // not enough cells → not a data row
    const rec = { line_no: lineNo, description: '', hsn_sac: '', quantity: null,
      unit: '', rate: null, unit_price: null, gst_rate: null, amount: null };
    pre.forEach((k, idx) => assignCol(rec, k, toks[idx]));                    // leading cols
    post.forEach((k, idx) => assignCol(rec, k, toks[toks.length - post.length + idx])); // trailing cols
    rec.description = toks.slice(pre.length, toks.length - post.length).join(' '); // the middle
    if (rec.description || rec.amount != null) { items.push(rec); lineNo++; }
  }
  return items;
}

function allGstins(ls) {
  const out = [];
  ls.forEach((l) => { const m = l.match(GSTIN_RE); if (m) out.push({ gstin: m[0], line: l }); });
  return out;
}

function parseInvoice(text) {
  const ls = lines(text);
  const gs = allGstins(ls);
  const buyer = gs.find((g) => /bill\s*to|buyer|consignee|ship\s*to/i.test(g.line));
  const seller = gs.find((g) => g !== buyer);
  // vendor name = first non-generic header line
  const vname = (ls.find((l) => !/^(tax\s*invoice|invoice|gstin|bill\s*to)/i.test(l)
    && /[A-Za-z]{3,}/.test(l)) || '').replace(/\s{2,}.*$/, '');
  const poref = fieldValue(text, ['buyer\\s*po\\s*ref', 'po\\s*ref', 'p\\.?o\\.?\\s*no', 'purchase\\s*order', 'po']);
  const cgst = grabTax(text, 'cgst');
  const sgst = grabTax(text, 'sgst');
  const igst = grabTax(text, 'igst');
  let tax = toNum(fieldValue(text, ['tax\\s*amount', 'total\\s*tax', 'gst\\s*amount']));
  if (tax == null && (cgst != null || sgst != null || igst != null)) tax = (cgst || 0) + (sgst || 0) + (igst || 0);
  const poval = poref.match(/(PO|PR)?[-\s]?\d+/i);
  return {
    invoice_number: idValue(text, ['invoice\\s*no', 'invoice\\s*number', 'bill\\s*no', 'inv\\s*no']),
    invoice_date: toIso(fieldValue(text, ['invoice\\s*date', 'date\\s*of\\s*issue', 'dated', 'date'])),
    vendor_name: vname,
    vendor_gstin: seller ? seller.gstin : '',
    buyer_gstin: buyer ? buyer.gstin : '',
    references: poval ? [{ value: poval[0].replace(/\s/g, ''), kind: 'buyer_pr_po', handwritten: false }] : [],
    taxable_total: toNum(fieldValue(text, ['taxable\\s*value', 'taxable', 'sub\\s*total', 'net\\s*amount'])),
    tax_total: tax,
    total: toNum(fieldValue(text, ['grand\\s*total', 'total\\s*due', 'amount\\s*payable', 'invoice\\s*total', 'total'])),
    lines: parseLineItems(ls),
  };
}

function parsePo(text) {
  const ls = lines(text);
  const gs = allGstins(ls);
  const vendor = gs.find((g) => /vendor|supplier/i.test(g.line));
  const buyer = gs.find((g) => g !== vendor);
  const vname = fieldValue(text, ['vendor', 'supplier']) || '';
  return {
    po_number: idValue(text, ['po\\s*number', 'po\\s*no', 'purchase\\s*order\\s*no', 'purchase\\s*order']),
    pr_number: idValue(text, ['pr\\s*number', 'pr\\s*no', 'requisition\\s*no']),
    vendor_name: vname.replace(/\s{2,}.*$/, ''),
    vendor_gstin: vendor ? vendor.gstin : (gs[1] ? gs[1].gstin : ''),
    buyer_gstin: buyer ? buyer.gstin : '',
    requisition_date: toIso(fieldValue(text, ['requisition\\s*date', 'po\\s*date', 'order\\s*date', 'date'])),
    total: toNum(fieldValue(text, ['po\\s*total', 'grand\\s*total', 'total'])),
    lines: parseLineItems(ls),
  };
}

function parseDoc(text, kind) { return kind === 'po' ? parsePo(text) : parseInvoice(text); }

// ---- n8n Code-node entrypoint (safe no-op under Node) --------------------- //
if (typeof $input !== 'undefined') {
  // Expects two "Extract from File" nodes upstream named as below, each exposing
  // the extracted text in json.text.
  const invText = $('Extract invoice text').first().json.text;
  const poText = $('Extract PO text').first().json.text;
  return [{ json: { invoice: parseInvoice(invText), pos: [parsePo(poText)], opts: {} } }]; // eslint-disable-line
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseInvoice, parsePo, parseDoc };
}

'use strict';
/*
 * normalize.js — map raw parsed input (OCR output or mock JSON) to the canonical
 * schema that matcher.js expects. Tolerates the alternate field names OCR services
 * and different vendors emit ("invoice_no" vs "invoice_number", "₹1,234.50" vs a
 * number, "line_items" vs "lines"). Numbers are cleaned to plain floats; dates are
 * left as ISO strings (the OCR step should already have normalised them).
 *
 * Accepts a payload shaped as { invoice, pos|po, opts? } where invoice/po may use
 * loose field names, and returns { invoice, pos, opts } in canonical form.
 */

const toNum = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const s = String(v).replace(/[₹$€£,\s]/g, '').replace(/[()]/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const pick = (obj, keys) => {
  for (const k of keys) if (obj && obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  return undefined;
};

function normRefs(raw) {
  // Accept: array of {value,kind,handwritten} | array of strings | a single "po_reference"
  if (!raw) return [];
  const arr = Array.isArray(raw) ? raw : [raw];
  return arr.map((r) =>
    typeof r === 'string'
      ? { value: r, kind: 'buyer_pr_po', handwritten: false }
      : { value: r.value ?? r.ref ?? '', kind: r.kind || 'buyer_pr_po', handwritten: !!r.handwritten }
  ).filter((r) => r.value);
}

function normLines(raw) {
  const arr = raw || [];
  return arr.map((l, i) => ({
    line_no: l.line_no ?? i + 1,
    description: pick(l, ['description', 'desc', 'item', 'particulars', 'name']) || '',
    hsn_sac: pick(l, ['hsn_sac', 'hsn', 'sac', 'hsn_code']) || '',
    quantity: toNum(pick(l, ['quantity', 'qty'])),
    unit: pick(l, ['unit', 'uom']) || '',
    rate: toNum(pick(l, ['rate', 'unit_price', 'price'])),
    unit_price: toNum(pick(l, ['unit_price', 'rate', 'price'])),
    gst_rate: toNum(pick(l, ['gst_rate', 'gst', 'tax_rate'])),
    amount: toNum(pick(l, ['amount', 'line_total', 'total'])),
  }));
}

function normInvoice(raw) {
  if (!raw) return {};
  return {
    invoice_number: pick(raw, ['invoice_number', 'invoice_no', 'invoice', 'bill_no']) || '',
    invoice_date: pick(raw, ['invoice_date', 'date', 'invoice_dt']) || '',
    vendor_name: pick(raw, ['vendor_name', 'seller', 'supplier', 'vendor']) || '',
    vendor_gstin: pick(raw, ['vendor_gstin', 'seller_gstin', 'gstin', 'supplier_gstin']) || '',
    buyer_gstin: pick(raw, ['buyer_gstin', 'consignee_gstin']) || '',
    references: normRefs(raw.references || raw.po_reference || raw.buyer_pr_po),
    taxable_total: toNum(pick(raw, ['taxable_total', 'taxable', 'sub_total', 'subtotal'])),
    tax_total: toNum(pick(raw, ['tax_total', 'gst', 'tax', 'gst_total'])),
    total: toNum(pick(raw, ['total', 'grand_total', 'invoice_amount', 'amount_due'])),
    lines: normLines(raw.lines || raw.line_items || raw.items),
  };
}

function normPo(raw) {
  if (!raw) return null;
  const lines = normLines(raw.lines || raw.line_items || raw.items);
  // po_itemized: >1 line, OR a single line with qty>1 AND a per-unit price
  let itemized = raw.po_itemized;
  if (itemized === undefined) {
    if (lines.length > 1) itemized = true;
    else if (lines.length === 1) itemized = (lines[0].quantity > 1 && lines[0].unit_price != null);
    else itemized = false;
  }
  return {
    po_number: pick(raw, ['po_number', 'po_no', 'po']) || '',
    pr_number: pick(raw, ['pr_number', 'pr_no', 'pr']) || '',
    vendor_name: pick(raw, ['vendor_name', 'supplier', 'vendor']) || '',
    vendor_gstin: pick(raw, ['vendor_gstin', 'supplier_gstin', 'gstin']) || '',
    buyer_gstin: pick(raw, ['buyer_gstin']) || '',
    requisition_date: pick(raw, ['requisition_date', 'po_date', 'date']) || '',
    scheduled_date: pick(raw, ['scheduled_date']) || '',
    total: toNum(pick(raw, ['total', 'grand_total', 'po_total'])),
    po_itemized: !!itemized,
    lines,
  };
}

function normalize(payload) {
  const invoice = normInvoice(payload.invoice);
  const posRaw = payload.pos || (payload.po ? [payload.po] : []);
  const pos = posRaw.map(normPo).filter(Boolean);
  return { invoice, pos, opts: payload.opts || {} };
}

if (typeof $input !== 'undefined') {
  const out = $input.all().map((it) => ({ json: normalize(it.json) }));
  return out;                                                   // eslint-disable-line
}
if (typeof module !== 'undefined' && module.exports) module.exports = { normalize, toNum };

'use strict';
/*
 * matcher.js — Two-way Invoice ↔ PO match (GST rules).
 *
 * A faithful, two-way-only reduction of the four-way purchase-match skill in
 * ../../purchase-four-way-match/references/check-rules.md. GRN, register and
 * bundle mechanics are dropped; the invoice is the anchor and we match it to one
 * or more POs.
 *
 * Design invariants carried over from the reference:
 *   - THREE STATES everywhere: 'agrees' | 'fails' | 'unverified'. Missing data is
 *     NEVER coerced to 0/false — it is 'unverified', and 'unverified' NEVER flips
 *     the verdict.
 *   - Only Tier-1 header checks (vendor / total / dates-in-FY) drive the verdict.
 *     Everything else (HSN, GST%, over-billing, rate variance, date order, line
 *     pairing) is a FLAG that is reported but never changes Match / No match.
 *   - An invoice may legitimately span several POs → we gather a LIST of matched
 *     POs and reconcile the invoice total against their SUM.
 *
 * Portable: runs unchanged in Node (require) and in an n8n Code node.
 */

// --------------------------------------------------------------------------- //
// Tolerances — verbatim from check-rules.md § "Tolerances (one place)"         //
// --------------------------------------------------------------------------- //
const round2 = (x) => Math.round((Number(x) + Number.EPSILON) * 100) / 100;
const num = (x) => (x === null || x === undefined || x === '' ? null : Number(x));

const amountsEqual = (a, b) => Math.abs(a - b) <= Math.max(1.0, 0.005 * Math.abs(b)); // ₹1 or 0.5%
const ratesEqual = (a, b) => Math.abs(round2(a) - round2(b)) <= 0.01;
const pctEqual = (a, b) => Math.abs(a - b) <= 0.0001;                                  // 0.18 == 0.18
const qtyLe = (a, b) => a <= b + 1e-9;                                                 // directional

// --------------------------------------------------------------------------- //
// HSN/SAC → GST% master (bundled from the reference gst-hsn-rates.csv).         //
// A caller may pass an override map via opts.rateTable.                         //
// --------------------------------------------------------------------------- //
const DEFAULT_RATE_TABLE = {
  '3808': 18, '8516': 18, '85161000': 18, '9405': 18, '996609': 18,
  '3917': 18, '3925': 18, '8481': 18, '7307': 18, '3922': 18,
  '9954': 18, '995469': 18, '9985': 18, '998533': 18, '9987': 18,
  '99871': 18, '998311': 18, '9983': 18, '9401': 18, '9403': 18,
  '9404': 18, '4418': 18, '8302': 18, '4819': 18, '9405XX': 18,
  '6307': 12, '5208': 5,
};

// --------------------------------------------------------------------------- //
// small helpers                                                                //
// --------------------------------------------------------------------------- //
const normGstin = (g) => (g ? String(g).toUpperCase().replace(/\s+/g, '') : '');
const gstinEqual = (a, b) => {
  const x = normGstin(a), y = normGstin(b);
  return x && y ? x === y : null; // null == "can't tell" (one missing)
};

const normName = (s) =>
  String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\b(private|pvt|limited|ltd|llp|inc|co|company|and|the)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

// normalise a PO/PR number for comparison: "PR 2390" ~ "PR2390" ~ "pr-2390"
const normRef = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

const inFY = (d, fyStart, fyEnd) => d >= fyStart && d <= fyEnd;

const SYNONYMS = [['elbow', 'bend']];
const STOP = new Set(['mm', 'inch', 'in', 'approx', 'approximately', 'set', 'sets',
  'pcs', 'pc', 'nos', 'no', 'of', 'the', 'for', 'and', 'with', 'x', 'size', 'grade']);
function normDesc(s) {
  let t = String(s || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ');
  for (const [a, b] of SYNONYMS) t = t.replace(new RegExp('\\b' + b + '\\b', 'g'), a);
  const toks = t.split(/\s+/).filter((w) => w && !STOP.has(w));
  return toks.join(' ').trim();
}
function sameProduct(a, b) {
  const na = normDesc(a), nb = normDesc(b);
  if (!na || !nb) return false;
  if (na === nb) return true;
  if (na.includes(nb) || nb.includes(na)) return true;
  const A = new Set(na.split(' ')), B = new Set(nb.split(' '));
  let inter = 0;
  for (const w of A) if (B.has(w)) inter += 1;
  const jac = inter / (A.size + B.size - inter);
  return jac >= 0.6;
}

// --------------------------------------------------------------------------- //
// 1. Match ladder (Hop 2) — gather ALL matching POs into matched_pos           //
// --------------------------------------------------------------------------- //
function buildLadder(invoice, pos) {
  const refs = (invoice.references || []).filter((r) => r.kind === 'buyer_pr_po');
  const refVals = refs.map((r) => normRef(r.value));
  const handwritten = refs.some((r) => r.handwritten);

  // Rung 1 — explicit PR/PO reference
  const rung1 = pos.filter((po) =>
    refVals.includes(normRef(po.po_number)) || refVals.includes(normRef(po.pr_number)));
  if (rung1.length) {
    return {
      matched: rung1,
      basis: handwritten ? 'PR/PO (handwritten, review)' : 'PR/PO number',
      confidence: handwritten ? 'medium' : 'high',
      rung: 1,
    };
  }

  // Rung 2 — fingerprint: GSTIN + total
  const rung2 = pos.filter((po) =>
    gstinEqual(invoice.vendor_gstin, po.vendor_gstin) === true &&
    invoice.total != null && po.total != null &&
    amountsEqual(invoice.total, po.total));
  if (rung2.length) {
    return { matched: rung2, basis: 'GSTIN + total', confidence: 'medium', rung: 2 };
  }

  // Rung 3 — GSTIN matches but total off (tentative; total check will fail)
  const rung3 = pos.filter((po) => gstinEqual(invoice.vendor_gstin, po.vendor_gstin) === true);
  if (rung3.length) {
    return { matched: rung3, basis: 'possible match (GSTIN only)', confidence: 'low', rung: 3 };
  }

  // Rung 4 — nothing ties (does NOT force No-match)
  return { matched: [], basis: 'No PO found', confidence: 'none', rung: 4 };
}

// --------------------------------------------------------------------------- //
// 2. Line pairing (Tier 4)                                                     //
// --------------------------------------------------------------------------- //
function pairLines(invLines, poLines) {
  const paired = new Map();       // invoice line_no -> po line ref
  const usedPo = new Set();

  const poKey = (l) => (l.hsn_sac ? String(l.hsn_sac) : '') + '|' + normDesc(l.description);

  // (1) exact key: identical normalised description OR exact HSN
  for (const il of invLines) {
    for (const pl of poLines) {
      if (usedPo.has(pl._ref)) continue;
      const exactHsn = il.hsn_sac && pl.hsn_sac && String(il.hsn_sac) === String(pl.hsn_sac);
      if (normDesc(il.description) === normDesc(pl.description) || exactHsn) {
        paired.set(il.line_no, pl); usedPo.add(pl._ref); break;
      }
    }
  }
  // (2) same-product judgment for the rest
  for (const il of invLines) {
    if (paired.has(il.line_no)) continue;
    for (const pl of poLines) {
      if (usedPo.has(pl._ref)) continue;
      if (sameProduct(il.description, pl.description)) {
        paired.set(il.line_no, pl); usedPo.add(pl._ref); break;
      }
    }
  }
  // (3) 1-to-1 elimination fallback
  const leftInv = invLines.filter((il) => !paired.has(il.line_no));
  const leftPo = poLines.filter((pl) => !usedPo.has(pl._ref));
  if (leftInv.length && leftInv.length === leftPo.length && leftInv.length <= 3) {
    leftInv.forEach((il, i) => { paired.set(il.line_no, leftPo[i]); usedPo.add(leftPo[i]._ref); });
  }
  return { paired, usedPo };
}

// --------------------------------------------------------------------------- //
// main                                                                         //
// --------------------------------------------------------------------------- //
function runMatch(input, opts = {}) {
  const invoice = input.invoice || {};
  const pos = input.pos || (input.po ? [input.po] : []);
  const fyStart = opts.fy_start || '2025-04-01';
  const fyEnd = opts.fy_end || '2026-03-31';
  const rateTable = opts.rateTable || DEFAULT_RATE_TABLE;
  const flags = [];

  // ---- ladder ---------------------------------------------------------- //
  const ladder = buildLadder(invoice, pos);
  const matched = ladder.matched;
  const poTotalSum = matched.reduce((s, p) => s + (num(p.total) || 0), 0);
  const isLumpSum = matched.length === 1 && matched[0].po_itemized === false;

  if (ladder.rung === 4) flags.push('No PO matched (PO checks unverified)');
  if (ladder.rung === 3) flags.push('Possible match only (GSTIN, total off)');
  if (ladder.confidence === 'medium' && ladder.basis.includes('handwritten'))
    flags.push('PR/PO reference is handwritten — review');
  if (matched.length > 1) flags.push(`Invoice spans ${matched.length} POs (total vs Σ POs)`);
  if (isLumpSum) flags.push('PO is lump-sum — per-line checks N/A');

  // ---- Tier 1 header checks (verdict-driving) -------------------------- //
  const checks = {};

  // vendor_match
  if (!matched.length) {
    checks.vendor_match = 'unverified';
  } else {
    let verdict = 'agrees';
    for (const po of matched) {
      const g = gstinEqual(invoice.vendor_gstin, po.vendor_gstin);
      if (g === true) continue;
      if (g === false) { verdict = 'fails'; break; }
      // GSTIN missing → fall back to normalized name
      if (invoice.vendor_name && po.vendor_name) {
        if (normName(invoice.vendor_name) !== normName(po.vendor_name)) { verdict = 'fails'; break; }
      } else { verdict = 'unverified'; }
    }
    checks.vendor_match = verdict;
  }

  // total_match
  if (!matched.length || invoice.total == null) {
    checks.total_match = 'unverified';
  } else {
    checks.total_match = amountsEqual(num(invoice.total), poTotalSum) ? 'agrees' : 'fails';
  }

  // dates_fy
  const dates = [];
  if (invoice.invoice_date) dates.push(['invoice', invoice.invoice_date]);
  for (const po of matched) if (po.requisition_date) dates.push([`PO ${po.po_number}`, po.requisition_date]);
  const outside = dates.find(([, d]) => !inFY(d, fyStart, fyEnd));
  const needMissing = !invoice.invoice_date || matched.some((p) => !p.requisition_date);
  if (outside) checks.dates_fy = 'fails';
  else if (needMissing) checks.dates_fy = 'unverified';
  else checks.dates_fy = 'agrees';

  // ---- verdict --------------------------------------------------------- //
  const headerFails =
    checks.vendor_match === 'fails' ||
    checks.total_match === 'fails' ||
    checks.dates_fy === 'fails';
  const result = !invoice.invoice_number && !invoice.total ? '' : headerFails ? 'No match' : 'Match';

  // ---- po_num_consistent (flag) --------------------------------------- //
  const invRefs = (invoice.references || []).filter((r) => r.kind === 'buyer_pr_po');
  if (!matched.length || invRefs.length === 0) {
    checks.po_num_consistent = 'unverified';
  } else {
    const matchedRefs = new Set();
    matched.forEach((p) => { matchedRefs.add(normRef(p.po_number)); matchedRefs.add(normRef(p.pr_number)); });
    const stray = invRefs.find((r) => !matchedRefs.has(normRef(r.value)));
    checks.po_num_consistent = stray ? 'fails' : 'agrees';
    if (stray) flags.push(`Invoice cites PR/PO ${stray.value} that matches no PO`);
  }

  // ---- date_order (flag, hard red) ------------------------------------ //
  const latestPoDate = matched.map((p) => p.requisition_date).filter(Boolean).sort().pop();
  if (invoice.invoice_date && latestPoDate) {
    checks.date_order = invoice.invoice_date >= latestPoDate ? 'agrees' : 'fails';
    if (checks.date_order === 'fails')
      flags.push(`Invoice dated ${invoice.invoice_date} is BEFORE PO ${latestPoDate}`);
  } else {
    checks.date_order = 'unverified';
  }

  // ---- Tier 2/3/4 per-line ------------------------------------------- //
  const poLines = [];
  matched.forEach((po, pi) =>
    (po.lines || []).forEach((l, li) => poLines.push({ ...l, _ref: `${pi}:${li}`, _po: po.po_number })));
  const invLines = invoice.lines || [];
  const { paired } = isLumpSum ? { paired: new Map() } : pairLines(invLines, poLines);

  let overBilled = 0, rateVar = 0, hsnBad = 0, gstBad = 0, billOnly = 0;
  const lines = invLines.map((il) => {
    const pl = paired.get(il.line_no);

    // Tier 2 — HSN validity + GST correctness (always runs, even lump-sum)
    const hsn = il.hsn_sac ? String(il.hsn_sac).replace(/\s+/g, '') : '';
    let hsn_valid = 'unverified';
    if (hsn) {
      const okLen = [4, 6, 8].includes(hsn.length) && /^[0-9]+$/.test(hsn);
      const sacOk = hsn.length === 6 && hsn.startsWith('99');
      hsn_valid = okLen || sacOk ? 'agrees' : 'fails';
      if (hsn_valid === 'fails') hsnBad += 1;
    }
    let gst_correct = 'unverified';
    if (hsn && rateTable[hsn] != null && il.gst_rate != null) {
      gst_correct = pctEqual(num(il.gst_rate), rateTable[hsn] / 100) ? 'agrees' : 'fails';
      if (gst_correct === 'fails') gstBad += 1;
    }

    // Tier 3/4 — pairing-dependent
    let line_match, rate_match, qty_flag;
    if (isLumpSum) {
      line_match = 'N/A — PO lump-sum'; rate_match = 'unverified'; qty_flag = 'N/A — PO lump-sum';
    } else if (pl) {
      line_match = 'agrees';
      rate_match = pl.unit_price != null && il.rate != null
        ? (ratesEqual(num(il.rate), num(pl.unit_price)) ? 'agrees' : 'fails')
        : 'unverified';
      if (rate_match === 'fails') rateVar += 1;
      if (il.quantity != null && pl.quantity != null) {
        qty_flag = qtyLe(num(il.quantity), num(pl.quantity)) ? 'agrees' : 'fails';
        if (qty_flag === 'fails') overBilled += 1;
      } else qty_flag = 'unverified';
    } else {
      line_match = matched.length ? 'fails' : 'unverified'; // extra billed line not on any PO
      rate_match = 'unverified'; qty_flag = 'unverified';
      if (matched.length) billOnly += 1;
    }

    return {
      line_no: il.line_no, description: il.description, hsn_sac: il.hsn_sac || '',
      quantity: il.quantity ?? '', unit: il.unit || '', rate: il.rate ?? '',
      gst_rate: il.gst_rate ?? '', amount: il.amount ?? '',
      paired_po_line: pl ? `${pl._po}#${pl.line_no}` : '', po_qty: pl ? (pl.quantity ?? '') : '',
      po_unit_price: pl ? (pl.unit_price ?? '') : '',
      line_match, rate_match, qty_flag, hsn_valid, gst_correct,
    };
  });

  // PO-only lines (ordered but not billed) — informational
  const poOnly = poLines.filter((pl) => ![...paired.values()].some((p) => p._ref === pl._ref));

  if (overBilled) flags.push(`Over-billed ${overBilled} line item(s) (billed > ordered)`);
  if (rateVar) flags.push(`Rate variance on ${rateVar} line(s)`);
  if (hsnBad) flags.push(`Invalid HSN/SAC on ${hsnBad} line(s)`);
  if (gstBad) flags.push(`GST% mismatch on ${gstBad} line(s)`);
  if (billOnly) flags.push(`${billOnly} billed line(s) not on any PO`);
  if (!isLumpSum && poOnly.length) flags.push(`${poOnly.length} ordered line(s) not billed`);

  // ---- duplicate detection (optional ledger of prior invoices) -------- //
  if (opts.ledger && opts.ledger.length) {
    for (const e of opts.ledger) {
      const sameVendor = gstinEqual(invoice.vendor_gstin, e.vendor_gstin) === true;
      if (sameVendor && e.invoice_number && invoice.invoice_number &&
          normRef(e.invoice_number) === normRef(invoice.invoice_number)) {
        flags.push(`EXACT DUPLICATE of already-processed invoice ${e.invoice_number}`);
      } else if (sameVendor && e.total != null && invoice.total != null &&
                 amountsEqual(num(invoice.total), num(e.total)) && e.invoice_date === invoice.invoice_date) {
        flags.push(`Possible duplicate: same vendor/amount/date as ${e.invoice_number} (diff number)`);
      }
    }
  }

  // ---- reason (only on No match) -------------------------------------- //
  let reason = '';
  if (result === 'No match') {
    const parts = [];
    if (checks.vendor_match === 'fails') parts.push('Invoice/PO vendor mismatch');
    if (checks.total_match === 'fails') {
      const d = round2(num(invoice.total) - poTotalSum);
      parts.push(`Invoice ${invoice.total} vs PO ${round2(poTotalSum)} (diff ${d})`);
    }
    if (checks.dates_fy === 'fails' && outside)
      parts.push(`${outside[0]} date ${outside[1]} outside FY ${fyStart}–${fyEnd}`);
    reason = parts.join('; ');
  }

  return {
    header: {
      invoice_number: invoice.invoice_number || '',
      invoice_date: invoice.invoice_date || '',
      vendor_name: invoice.vendor_name || '',
      vendor_gstin: invoice.vendor_gstin || '',
      invoice_total: invoice.total ?? '',
      matched_po_numbers: matched.map((p) => p.po_number).join(', ') +
        (matched.length > 1 ? ` (${matched.length})` : ''),
      po_total_sum: round2(poTotalSum),
      result,
      vendor_match: checks.vendor_match,
      total_match: checks.total_match,
      dates_fy: checks.dates_fy,
      po_num_consistent: checks.po_num_consistent,
      date_order: checks.date_order,
      match_basis: ladder.basis,
      confidence: ladder.confidence,
      flags,
      reason,
    },
    lines,
  };
}

// ---- n8n Code-node entrypoint (safe no-op under Node) --------------------- //
if (typeof $input !== 'undefined') {
  const payload = $input.first().json;                          // { invoice, pos|po, opts? }
  const out = runMatch(payload, payload.opts || {});
  return [{ json: out }];                                       // eslint-disable-line
}

// ---- Node export (safe no-op inside n8n) ---------------------------------- //
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { runMatch, amountsEqual, ratesEqual, pctEqual, qtyLe, DEFAULT_RATE_TABLE };
}

'use strict';
/*
 * to_rows.js — turn a matcher result into (a) flat rows and (b) CSV text, ready
 * for the "Convert to File" node or direct return to the browser. Produces two
 * logical tables: a one-row-per-invoice results table and a one-row-per-line
 * detail table, plus a combined CSV string for each.
 */

const RESULT_COLS = [
  'invoice_number', 'invoice_date', 'vendor_name', 'vendor_gstin', 'invoice_total',
  'matched_po_numbers', 'po_total_sum', 'result', 'vendor_match', 'total_match',
  'dates_fy', 'po_num_consistent', 'date_order', 'match_basis', 'confidence',
  'flags', 'reason',
];
const LINE_COLS = [
  'invoice_number', 'line_no', 'description', 'hsn_sac', 'quantity', 'unit', 'rate',
  'gst_rate', 'amount', 'paired_po_line', 'po_qty', 'po_unit_price', 'line_match',
  'rate_match', 'qty_flag', 'hsn_valid', 'gst_correct',
];

const csvCell = (v) => {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};
const toCsv = (cols, rows) =>
  [cols.join(','), ...rows.map((r) => cols.map((c) => csvCell(r[c])).join(','))].join('\n');

function toRows(result) {
  const h = result.header;
  const resultRow = { ...h, flags: (h.flags || []).join(' ; ') };
  const lineRows = (result.lines || []).map((l) => ({ invoice_number: h.invoice_number, ...l }));

  const resultsCsv = toCsv(RESULT_COLS, [resultRow]);
  const linesCsv = toCsv(LINE_COLS, lineRows);
  return {
    result: h.result,
    header: resultRow,
    lines: lineRows,
    results_csv: resultsCsv,
    lines_csv: linesCsv,
    // one combined workbook-style CSV (results block, blank line, line detail)
    combined_csv: resultsCsv + '\n\n' + linesCsv,
  };
}

if (typeof $input !== 'undefined') {
  const it = $input.first().json;
  const out = toRows(it);
  const csv = out.combined_csv;
  return [{                                                     // eslint-disable-line
    json: { result: out.result, header: out.header, lines: out.lines,
            csv_base64: Buffer.from(csv, 'utf8').toString('base64'),
            filename: `match_${out.header.invoice_number || 'result'}.csv` },
    binary: { data: { data: Buffer.from(csv, 'utf8').toString('base64'),
              mimeType: 'text/csv', fileName: `match_${out.header.invoice_number || 'result'}.csv` } },
  }];
}
if (typeof module !== 'undefined' && module.exports) module.exports = { toRows, RESULT_COLS, LINE_COLS };

'use strict';
/*
 * ocr_nanonets.js — map a Nanonets /LabelFile/ prediction response to the canonical
 * schema that normalize.js / matcher.js expect.
 *
 * Nanonets response shape (v2 model prediction):
 *   result[0].prediction[] -> [{ label, ocr_text, ... }]   (flat header fields)
 *   result[0].cells[]      -> [{ row, col, label, ocr_text }] (table / line items)
 *
 * Pretrained-model label names vary a little between the Invoice and Purchase-Order
 * models and across account versions, so the label map below is deliberately
 * TOLERANT (many aliases → one canonical key). Run tests/nanonets_probe.js to print
 * the *actual* labels your models emit, then add any missing alias here.
 *
 * Portable: runs in Node (require) and in an n8n Code node.
 */

// canonical key  ->  set of accepted Nanonets labels (lowercased, non-alnum stripped)
const HEADER_ALIASES = {
  invoice_number: ['invoicenumber', 'invoiceno', 'invoiceno', 'billno', 'billnumber'],
  invoice_date: ['invoicedate', 'date', 'billdate'],
  vendor_name: ['vendorname', 'sellername', 'suppliername', 'vendor', 'seller', 'frombusinessname', 'companyname'],
  vendor_gstin: ['vendorgstin', 'sellergstin', 'gstin', 'suppliergstin', 'gstinno', 'gstno', 'sellergstinuin'],
  buyer_gstin: ['buyergstin', 'consigneegstin', 'shiptogstin', 'billtogstin'],
  po_number: ['ponumber', 'pono', 'purchaseordernumber', 'purchaseorderno', 'buyerorderno', 'buyerpo'],
  pr_number: ['prnumber', 'prno', 'requisitionnumber'],
  requisition_date: ['requisitiondate', 'podate', 'purchaseorderdate', 'orderdate'],
  taxable_total: ['taxabletotal', 'taxableamount', 'taxablevalue', 'subtotal', 'nettotal'],
  tax_total: ['taxtotal', 'taxamount', 'gsttotal', 'gstamount', 'totaltax', 'gst'],
  total: ['total', 'totalamount', 'grandtotal', 'invoiceamount', 'invoicetotal', 'pototal', 'amountdue', 'amountpayable'],
};

// invoice/PO can print CGST + SGST separately — sum them into tax_total.
const SPLIT_TAX = ['cgst', 'cgstamount', 'sgst', 'sgstamount', 'igst', 'igstamount'];

const LINE_ALIASES = {
  description: ['description', 'itemdescription', 'lineitemdescription', 'particulars', 'itemname', 'product'],
  hsn_sac: ['hsn', 'sac', 'hsnsac', 'hsncode', 'hsnsaccode'],
  quantity: ['quantity', 'qty'],
  unit: ['unit', 'uom', 'units'],
  unit_price: ['unitprice', 'rate', 'price', 'priceperunit'],
  gst_rate: ['gstrate', 'gst', 'taxrate', 'gstpercent'],
  amount: ['amount', 'lineamount', 'linetotal', 'total', 'value'],
};

const key = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const cleanNum = (s) => {
  if (s === null || s === undefined || s === '') return null;
  const n = Number(String(s).replace(/[₹$€£,%\s]/g, '').replace(/[()]/g, ''));
  return Number.isFinite(n) ? n : null;
};

function findCanonical(labelKey, aliasMap) {
  for (const canon of Object.keys(aliasMap)) {
    if (aliasMap[canon].includes(labelKey)) return canon;
  }
  return null;
}

// pull result[0] (the first page/prediction block) defensively
function firstBlock(resp) {
  if (!resp) return { prediction: [], cells: [] };
  const r = Array.isArray(resp.result) ? resp.result[0] : resp.result || resp;
  return { prediction: r.prediction || [], cells: r.cells || [] };
}

function headerFields(prediction) {
  const out = {}; let splitTax = 0; let sawSplit = false;
  for (const p of prediction) {
    const lk = key(p.label);
    const val = p.ocr_text != null ? p.ocr_text : p.value;
    if (SPLIT_TAX.includes(lk)) { const n = cleanNum(val); if (n != null) { splitTax += n; sawSplit = true; } continue; }
    const canon = findCanonical(lk, HEADER_ALIASES);
    if (canon && out[canon] === undefined) out[canon] = val;
  }
  if (sawSplit && out.tax_total === undefined) out.tax_total = splitTax;
  return out;
}

function lineItems(cells) {
  if (!cells || !cells.length) return [];
  const rows = new Map();
  for (const c of cells) {
    const r = c.row;
    if (r === undefined || r === null) continue;
    if (!rows.has(r)) rows.set(r, {});
    const canon = findCanonical(key(c.label), LINE_ALIASES);
    if (canon) rows.get(r)[canon] = c.ocr_text != null ? c.ocr_text : c.value;
  }
  // Nanonets often includes the header row as row 0 with the column titles — drop any
  // row that has no numeric quantity/amount and whose description looks like a header.
  const items = [];
  let lineNo = 1;
  for (const [, cols] of [...rows.entries()].sort((a, b) => a[0] - b[0])) {
    const hasData = cols.description || cols.amount || cols.quantity;
    if (!hasData) continue;
    const looksHeader = /^(description|item|qty|quantity|rate|amount|hsn|sac|particulars)$/i
      .test(String(cols.description || '').trim());
    if (looksHeader) continue;
    items.push({
      line_no: lineNo++,
      description: cols.description || '',
      hsn_sac: cols.hsn_sac || '',
      quantity: cleanNum(cols.quantity),
      unit: cols.unit || '',
      rate: cleanNum(cols.unit_price),
      unit_price: cleanNum(cols.unit_price),
      gst_rate: normGst(cols.gst_rate),
      amount: cleanNum(cols.amount),
    });
  }
  return items;
}

// GST may come as "18", "18%", or "0.18" — canonical is a fraction (0.18).
function normGst(v) {
  const n = cleanNum(v);
  if (n == null) return null;
  return n > 1 ? n / 100 : n;
}

function nanonetsToCanonical(resp, kind) {
  const { prediction, cells } = firstBlock(resp);
  const h = headerFields(prediction);
  const lines = lineItems(cells);

  if (kind === 'po') {
    const doc = {
      po_number: h.po_number || '',
      pr_number: h.pr_number || '',
      vendor_name: h.vendor_name || '',
      vendor_gstin: h.vendor_gstin || '',
      buyer_gstin: h.buyer_gstin || '',
      requisition_date: h.requisition_date || h.invoice_date || '',
      total: cleanNum(h.total),
      lines,
    };
    return doc;
  }
  // invoice
  return {
    invoice_number: h.invoice_number || '',
    invoice_date: h.invoice_date || '',
    vendor_name: h.vendor_name || '',
    vendor_gstin: h.vendor_gstin || '',
    buyer_gstin: h.buyer_gstin || '',
    // a printed PO number on the invoice becomes a buyer_pr_po reference
    references: h.po_number ? [{ value: h.po_number, kind: 'buyer_pr_po', handwritten: false }] : [],
    taxable_total: cleanNum(h.taxable_total),
    tax_total: cleanNum(h.tax_total),
    total: cleanNum(h.total),
    lines,
  };
}

// ---- n8n Code-node entrypoint (safe no-op under Node) --------------------- //
if (typeof $input !== 'undefined') {
  // Expects the two OCR HTTP nodes upstream, referenced by name.
  const invResp = $('OCR: parse invoice').first().json;
  const poResp = $('OCR: parse PO').first().json;
  const invoice = nanonetsToCanonical(invResp, 'invoice');
  const po = nanonetsToCanonical(poResp, 'po');
  return [{ json: { invoice, pos: [po], opts: {} } }];        // eslint-disable-line
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { nanonetsToCanonical };
}
